"use strict";(self.webpackChunkajudafacitysistemas=self.webpackChunkajudafacitysistemas||[]).push([[3894],{5527:(o,n,e)=>{e.r(n),e.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>d,frontMatter:()=>t,metadata:()=>i,toc:()=>p});var a=e(4848),s=e(8453);const t={title:"Como descobrir o IP da impressora t\xe9rmica?",description:"O caminho r\xe1pido \xe9 simples: Passo 1: Confirme que a impressora tem Ethernet ou Wi-Fi. Passo 2: Escolha o modelo da sua impressora abaixo. Passo 3: Imprima a ..."},r=void 0,i={id:"configuracoes/como-descobrir-o-ip-da-impressora-termica-",title:"Como descobrir o IP da impressora t\xe9rmica?",description:"O caminho r\xe1pido \xe9 simples: Passo 1: Confirme que a impressora tem Ethernet ou Wi-Fi. Passo 2: Escolha o modelo da sua impressora abaixo. Passo 3: Imprima a ...",source:"@site/docs/configuracoes/como-descobrir-o-ip-da-impressora-termica-.mdx",sourceDirName:"configuracoes",slug:"/configuracoes/como-descobrir-o-ip-da-impressora-termica-",permalink:"/en/docs/configuracoes/como-descobrir-o-ip-da-impressora-termica-",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{title:"Como descobrir o IP da impressora t\xe9rmica?",description:"O caminho r\xe1pido \xe9 simples: Passo 1: Confirme que a impressora tem Ethernet ou Wi-Fi. Passo 2: Escolha o modelo da sua impressora abaixo. Passo 3: Imprima a ..."},sidebar:"tutorialSidebar",previous:{title:"Como Criar e Configurar a Chave do Google Maps no Facity Controle?",permalink:"/en/docs/configuracoes/como-criar-e-configurar-a-chave-do-google-maps-no-facity-controle-"},next:{title:"Como liberar o acesso \xe0 rede local no Google Chrome para usar a balan\xe7a integrada",permalink:"/en/docs/configuracoes/como-liberar-o-acesso-a-rede-local-no-google-chrome-para-usar-a-balanca-integrada"}},l={},p=[];function c(o){return(0,a.jsx)(a.Fragment,{children:(0,a.jsx)(a.Fragment,{children:(0,a.jsx)("div",{dangerouslySetInnerHTML:{__html:'\n  \n<p>O caminho r\xe1pido \xe9 simples:</p>\n\n\n\n<p><strong>Passo 1:</strong> Confirme que a impressora tem Ethernet ou Wi-Fi.</p>\n\n\n\n<p><strong>Passo 2:</strong> Escolha o modelo da sua impressora abaixo.</p>\n\n\n\n<p><strong>Passo 3:</strong> Imprima a folha de rede e procure por IP Address, Local IP ou Printer IP.</p>\n\n\n\n<p>Para descobrir o <strong>endere\xe7o IP de uma impressora t\xe9rmica</strong>, normalmente basta imprimir o <strong>autoteste</strong> ou a <strong>folha de configura\xe7\xe3o de rede</strong>. O procedimento \xe9 feito pelo bot\xe3o frontal <strong>Avan\xe7o</strong>, <strong>Avan\xe7a Papel</strong> ou <strong>Feed</strong>, sem instalar programas.</p>\n\n\n\n<div class="wp-block-group is-nowrap is-layout-flex wp-container-core-group-is-layout-1 wp-block-group-is-layout-flex">\n<div class="wp-block-columns is-layout-flex wp-container-core-columns-is-layout-1 wp-block-columns-is-layout-flex">\n<div class="wp-block-column is-layout-flow wp-block-column-is-layout-flow" style="flex-basis:100%">\n<blockquote class="wp-block-quote has-small-font-size is-layout-flow wp-block-quote-is-layout-flow">\n<h2 class="wp-block-heading" style="font-size:18px;font-style:normal;font-weight:700"><sup><mark style="background-color:rgba(0, 0, 0, 0)" class="has-inline-color has-contrast-color"><strong>O que voc\xea precisa encontrar:</strong> no papel impresso, procure por <strong>IP</strong>, <strong>IP Address</strong>, <strong>Local IP</strong> ou <strong>Printer IP</strong>.</mark></sup></h2>\n</blockquote>\n</div>\n</div>\n</div>\n\n\n\n<p><strong>Escolha o modelo da sua impressora:</strong></p>\n\n\n\n<ul class="wp-block-list">\n<li><a href="#antes-de-comecar">Antes de come\xe7ar</a></li>\n\n\n\n<li><a href="#bematech-mp-4200-th">Bematech MP-4200 TH</a></li>\n\n\n\n<li><a href="#elgin-i8">Elgin i8</a></li>\n\n\n\n<li><a href="#elgin-i9">Elgin i9 e i9 Full</a></li>\n\n\n\n<li><a href="#epson-tm-t20iii">Epson TM-T20III</a></li>\n\n\n\n<li><a href="#epson-tm-t20ii">Epson TM-T20 e TM-T20II</a></li>\n\n\n\n<li><a href="#xprinter-pos80">XPrinter e POS-80</a></li>\n\n\n\n<li><a href="#localizar-ip">Como localizar o IP no papel</a></li>\n\n\n\n<li><a href="#problemas">O IP n\xe3o apareceu</a></li>\n\n\n\n<li><a href="#perguntas-frequentes">Perguntas frequentes</a></li>\n</ul>\n\n\n\n<h2 class="wp-block-heading" id="antes-de-comecar">Antes de come\xe7ar</h2>\n\n\n\n<p>Antes de come\xe7ar, confirme:</p>\n\n\n\n<ol class="wp-block-list">\n<li>A impressora est\xe1 com uma bobina de papel instalada.</li>\n\n\n\n<li>A tampa est\xe1 completamente fechada, exceto quando o passo a passo pedir para abri-la.</li>\n\n\n\n<li>A impressora est\xe1 conectada \xe0 energia.</li>\n\n\n\n<li>O modelo possui conex\xe3o de rede <strong>Ethernet</strong> ou <strong>Wi-Fi</strong>.</li>\n</ol>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Importante:</strong> uma impressora conectada somente por USB ou cabo serial<br>      n\xe3o possui endere\xe7o IP pr\xf3prio. Alguns modelos s\xe3o vendidos em vers\xf5es USB e em vers\xf5es com rede;<br>      confira a conex\xe3o da sua unidade.</p>\n</blockquote>\n\n\n\n<h2 class="wp-block-heading">Resumo r\xe1pido: sequ\xeancia de cada modelo</h2>\n\n\n\n<figure class="wp-block-table"><table><thead><tr><th>Modelo</th><th>Sequ\xeancia r\xe1pida</th></tr></thead><tbody><tr><td><a href="#bematech-mp-4200-th">Bematech MP-4200 TH</a></td><td>Segurar Avan\xe7a Papel \u2192 ligar \u2192 soltar ao imprimir \u2192 <strong>n\xe3o apertar mais nada</strong>.</td></tr><tr><td><a href="#elgin-i8">Elgin i8</a></td><td>Segurar Avan\xe7o \u2192 ligar \u2192 esperar 2 segundos \u2192 soltar.</td></tr><tr><td><a href="#elgin-i9">Elgin i9 e i9 Full</a></td><td>Segurar Avan\xe7o \u2192 ligar \u2192 soltar quando a impress\xe3o come\xe7ar.</td></tr><tr><td><a href="#epson-tm-t20iii">Epson TM-T20III</a></td><td>Ligada \u2192 abrir tampa \u2192 segurar Feed \u2192 fechar tampa \u2192 soltar.</td></tr><tr><td><a href="#epson-tm-t20ii">Epson TM-T20 e TM-T20II</a></td><td>Segurar Feed \u2192 ligar \u2192 soltar ao imprimir \u2192 tocar Feed quando solicitado.</td></tr><tr><td><a href="#xprinter-pos80">XPrinter, XP-Q200, XP-80 e POS-80</a></td><td>Segurar Feed \u2192 ligar \u2192 soltar quando a impress\xe3o come\xe7ar.</td></tr></tbody></table></figure>\n\n\n\n<h2 class="wp-block-heading" id="bematech-mp-4200-th">Bematech MP-4200 TH</h2>\n\n\n\n<figure class="wp-block-image size-medium"><img style="max-width: 100%; height: auto;" loading="lazy" decoding="async" width="297" height="300" src="https://manual.facity.com.br/wp-content/uploads/2026/07/bematech-mp-4200-th-1-297x300.webp" alt="" class="wp-image-2003" srcset="https://manual.facity.com.br/wp-content/uploads/2026/07/bematech-mp-4200-th-1-297x300.webp 297w, https://manual.facity.com.br/wp-content/uploads/2026/07/bematech-mp-4200-th-1-1014x1024.webp 1014w, https://manual.facity.com.br/wp-content/uploads/2026/07/bematech-mp-4200-th-1-768x776.webp 768w, https://manual.facity.com.br/wp-content/uploads/2026/07/bematech-mp-4200-th-1-475x480.webp 475w, https://manual.facity.com.br/wp-content/uploads/2026/07/bematech-mp-4200-th-1.webp 1169w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<p>A MP-4200 TH imprime primeiro um pequeno menu. Para obter o autoteste,\n  <strong>n\xe3o selecione nenhuma op\xe7\xe3o</strong>: basta esperar.</p>\n\n\n\n<ol class="wp-block-list">\n<li>Desligue a impressora pela chave liga/desliga.</li>\n\n\n\n<li>Pressione e mantenha pressionado o bot\xe3o frontal <strong>Avan\xe7a Papel</strong>.</li>\n\n\n\n<li>Sem soltar o bot\xe3o, ligue a impressora.</li>\n\n\n\n<li>Quando a impress\xe3o come\xe7ar, solte o bot\xe3o.</li>\n\n\n\n<li>A impressora imprimir\xe1 um pequeno menu.</li>\n\n\n\n<li><strong>N\xe3o pressione o bot\xe3o novamente.</strong></li>\n\n\n\n<li>Aguarde alguns segundos: o autoteste ser\xe1 impresso automaticamente.</li>\n\n\n\n<li>Procure o endere\xe7o IP na folha.</li>\n</ol>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Resumo:</strong> <br>    Desligar \u2192 segurar Avan\xe7a Papel \u2192 ligar \u2192 soltar quando imprimir \u2192 n\xe3o apertar nada \u2192 aguardar.<br>  </p>\n</blockquote>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Aten\xe7\xe3o:</strong> n\xe3o aperte Avan\xe7o novamente depois que o menu sair.<br>      Um toque pode selecionar outro modo de funcionamento.</p>\n</blockquote>\n\n\n\n<h2 class="wp-block-heading" id="elgin-i8">Elgin i8</h2>\n\n\n\n<figure class="wp-block-image size-medium is-resized"><img loading="lazy" decoding="async" width="300" height="200" src="https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i8-300x200.webp" alt="" class="wp-image-2004" style="width:369px;height:auto; max-width: 100%; height: auto;" srcset="https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i8-300x200.webp 300w, https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i8-768x512.webp 768w, https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i8-720x480.webp 720w, https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i8.webp 960w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<p>Na Elgin i8, o tempo \xe9 importante: para o autoteste, solte o bot\xe3o ap\xf3s aproximadamente <strong>2 segundos</strong>.</p>\n\n\n\n<ol class="wp-block-list">\n<li>Desligue a impressora.</li>\n\n\n\n<li>Pressione e mantenha pressionado o bot\xe3o amarelo <strong>Avan\xe7o</strong>.</li>\n\n\n\n<li>Sem soltar o bot\xe3o, ligue a impressora.</li>\n\n\n\n<li>Conte aproximadamente <strong>2 segundos</strong>.</li>\n\n\n\n<li>Solte o bot\xe3o e aguarde a impress\xe3o.</li>\n\n\n\n<li>Procure por <strong>IP</strong> ou <strong>IP Address</strong>.</li>\n</ol>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Resumo:</strong> <br>    Desligar \u2192 segurar Avan\xe7o \u2192 ligar \u2192 esperar 2 segundos \u2192 soltar.<br>  </p>\n</blockquote>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>N\xe3o segure por muito tempo:</strong> cerca de 10 segundos ativa o modo hexadecimal;<br>      cerca de 20 segundos pode iniciar o reset das configura\xe7\xf5es.</p>\n</blockquote>\n\n\n\n<h2 class="wp-block-heading" id="elgin-i9">Elgin i9 e Elgin i9 Full</h2>\n\n\n\n<figure class="wp-block-image size-medium is-resized"><img loading="lazy" decoding="async" width="300" height="200" src="https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i9-i9-full-300x200.webp" alt="" class="wp-image-2005" style="width:380px;height:auto; max-width: 100%; height: auto;" srcset="https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i9-i9-full-300x200.webp 300w, https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i9-i9-full-768x512.webp 768w, https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i9-i9-full-720x480.webp 720w, https://manual.facity.com.br/wp-content/uploads/2026/07/elgin-i9-i9-full.webp 960w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<p>O mesmo procedimento \xe9 usado na <strong>Elgin i9</strong> e na <strong>Elgin i9 Full</strong>.</p>\n\n\n\n<ol class="wp-block-list">\n<li>Desligue a impressora.</li>\n\n\n\n<li>Pressione e mantenha pressionado o bot\xe3o amarelo <strong>Avan\xe7o</strong>.</li>\n\n\n\n<li>Sem soltar o bot\xe3o, ligue a impressora.</li>\n\n\n\n<li>Continue segurando at\xe9 a impress\xe3o come\xe7ar.</li>\n\n\n\n<li>Assim que o papel come\xe7ar a sair, solte o bot\xe3o.</li>\n\n\n\n<li>Aguarde o autoteste terminar e procure o endere\xe7o IP.</li>\n</ol>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Resumo:</strong> <br>    Desligar \u2192 segurar Avan\xe7o \u2192 ligar \u2192 soltar quando come\xe7ar a imprimir.<br>  </p>\n</blockquote>\n\n\n\n<p></p>\n\n\n\n<h2 class="wp-block-heading" id="epson-tm-t20ii">Epson TM-T20 e Epson TM-T20II</h2>\n\n\n\n<figure class="wp-block-image size-medium is-resized"><img loading="lazy" decoding="async" width="300" height="200" src="https://manual.facity.com.br/wp-content/uploads/2026/07/epson-tm-t20-t20ii-300x200.webp" alt="" class="wp-image-2006" style="width:386px;height:auto; max-width: 100%; height: auto;" srcset="https://manual.facity.com.br/wp-content/uploads/2026/07/epson-tm-t20-t20ii-300x200.webp 300w, https://manual.facity.com.br/wp-content/uploads/2026/07/epson-tm-t20-t20ii-768x512.webp 768w, https://manual.facity.com.br/wp-content/uploads/2026/07/epson-tm-t20-t20ii-720x480.webp 720w, https://manual.facity.com.br/wp-content/uploads/2026/07/epson-tm-t20-t20ii.webp 960w" sizes="(min-width: 960px) 75vw, 100vw" /></figure>\n\n\n\n<p>Na TM-T20II, o autoteste acontece em duas etapas. A primeira folha mostra o estado atual da impressora;\n  depois, um toque curto em Feed continua o teste.</p>\n\n\n\n<ol class="wp-block-list">\n<li>Coloque papel, feche a tampa e desligue a impressora.</li>\n\n\n\n<li>Pressione e mantenha pressionado o bot\xe3o <strong>Feed</strong>.</li>\n\n\n\n<li>Sem soltar o bot\xe3o, ligue a impressora.</li>\n\n\n\n<li>Quando a impress\xe3o come\xe7ar, solte o bot\xe3o.</li>\n\n\n\n<li>Leia a primeira folha e procure as informa\xe7\xf5es de rede.</li>\n\n\n\n<li>Quando a impressora parar e o LED de papel piscar, pressione <strong>Feed uma vez, rapidamente</strong>.</li>\n\n\n\n<li>Aguarde a conclus\xe3o do autoteste.</li>\n</ol>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Resumo:</strong> <br>    Desligar \u2192 segurar Feed \u2192 ligar \u2192 soltar ao imprimir \u2192 tocar Feed uma vez quando parar.<br>  </p>\n</blockquote>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>O IP pode n\xe3o aparecer:</strong> dependendo da vers\xe3o e da interface Ethernet instalada,<br>      o autoteste frontal da TM-T20/TM-T20II pode mostrar apenas dados gerais.<br>      Nesse caso, tire uma foto da folha completa e envie ao suporte.</p>\n</blockquote>\n\n\n\n<p></p>\n\n\n\n<h2 class="wp-block-heading" id="epson-tm-t20iii">Epson TM-T20III</h2>\n\n\n\n<p>Na TM-T20III, o procedimento frontal abaixo imprime a\n  <strong>folha de status da interface de rede</strong>. A impressora deve permanecer ligada.</p>\n\n\n\n<ol class="wp-block-list">\n<li>Ligue a impressora normalmente e aguarde at\xe9 ela ficar pronta.</li>\n\n\n\n<li>Abra a tampa da bobina.</li>\n\n\n\n<li>Pressione o bot\xe3o frontal <strong>Feed</strong> e mantenha-o pressionado por pelo menos 1 segundo.</li>\n\n\n\n<li>Sem soltar o bot\xe3o, feche a tampa da bobina.</li>\n\n\n\n<li>Solte o bot\xe3o.</li>\n\n\n\n<li>Aguarde a folha de rede ser impressa.</li>\n\n\n\n<li>Procure pelo campo <strong>IP Address</strong>.</li>\n</ol>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Resumo:</strong> <br>    Deixar ligada \u2192 abrir a tampa \u2192 segurar Feed \u2192 fechar a tampa sem soltar \u2192 soltar.<br>  </p>\n</blockquote>\n\n\n\n<p></p>\n\n\n\n<h2 class="wp-block-heading" id="xprinter-pos80">XPrinter, XP-Q200, XP-80 e impressoras POS-80</h2>\n\n\n\n<p>Na maioria das impressoras XPrinter e dos modelos gen\xe9ricos de 80 mm, o autoteste \xe9 iniciado ao ligar o equipamento\n  com o bot\xe3o <strong>Feed</strong> pressionado.</p>\n\n\n\n<ol class="wp-block-list">\n<li>Desligue a impressora.</li>\n\n\n\n<li>Pressione e mantenha pressionado o bot\xe3o <strong>Feed</strong>.</li>\n\n\n\n<li>Sem soltar o bot\xe3o, ligue a impressora.</li>\n\n\n\n<li>Continue segurando at\xe9 a impress\xe3o come\xe7ar.</li>\n\n\n\n<li>Solte o bot\xe3o assim que o papel come\xe7ar a sair.</li>\n\n\n\n<li>Aguarde o autoteste e procure por <strong>IP Address</strong>, <strong>Local IP</strong> ou <strong>Printer IP</strong>.</li>\n</ol>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Resumo:</strong> <br>    Desligar \u2192 segurar Feed \u2192 ligar \u2192 soltar quando come\xe7ar a imprimir.<br>  </p>\n</blockquote>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p><strong>Modelos gen\xe9ricos podem variar:</strong> nomes como POS-80, XP-80 e POS-80C s\xe3o usados por v\xe1rios fabricantes.<br>      Se o procedimento n\xe3o funcionar, confira a etiqueta inferior e procure o modelo completo.</p>\n</blockquote>\n\n\n\n<h2 class="wp-block-heading" id="localizar-ip">Como localizar o IP no papel</h2>\n\n\n\n<p>Procure por um destes nomes:</p>\n\n\n\n<ul class="wp-block-list">\n<li><strong>IP</strong> ou <strong>IP Address</strong>;</li>\n\n\n\n<li><strong>Current IP</strong>;</li>\n\n\n\n<li><strong>Local IP</strong> ou <strong>Printer IP</strong>;</li>\n\n\n\n<li><strong>TCP/IP</strong>;</li>\n\n\n\n<li><strong>Ethernet</strong> ou <strong>Network Configuration</strong>.</li>\n</ul>\n\n\n\n<p>Exemplo:</p>\n\n\n\n<pre class="wp-block-code"><code>ETHERNET CONFIGURATION\nDHCP: ENABLE\nIP ADDRESS: 192.168.1.150\nSUBNET MASK: 255.255.255.0\nGATEWAY: 192.168.1.1\nMAC ADDRESS: 00-11-22-33-44-55</code></pre>\n\n\n\n<blockquote class="wp-block-quote is-layout-flow wp-block-quote-is-layout-flow">\n<p>Nesse exemplo, o IP da impressora \xe9 <strong>192.168.1.150</strong>.</p>\n</blockquote>\n\n\n\n<figure class="wp-block-table"><table><thead><tr><th>Informa\xe7\xe3o</th><th>Exemplo</th><th>\xc9 o n\xfamero procurado?</th></tr></thead><tbody><tr><td>IP Address</td><td><code>192.168.1.150</code></td><td><strong>Sim</strong></td></tr><tr><td>Subnet Mask</td><td><code>255.255.255.0</code></td><td>N\xe3o</td></tr><tr><td>Gateway</td><td><code>192.168.1.1</code></td><td>N\xe3o</td></tr><tr><td>MAC Address</td><td><code>00-11-22-33-44-55</code></td><td>N\xe3o</td></tr></tbody></table></figure>\n\n\n\n<h2 class="wp-block-heading" id="problemas">O papel foi impresso, mas o IP n\xe3o apareceu</h2>\n\n\n\n<h3 class="wp-block-heading">1. A impressora pode ser somente USB ou serial</h3>\n\n\n\n<p>Um mesmo modelo pode existir em vers\xf5es diferentes. Somente vers\xf5es com Ethernet ou Wi-Fi possuem IP pr\xf3prio.</p>\n\n\n\n<h3 class="wp-block-heading">2. O autoteste pode n\xe3o mostrar a configura\xe7\xe3o da rede</h3>\n\n\n\n<p>Isso acontece em algumas interfaces, especialmente em determinadas vers\xf5es da Epson TM-T20/TM-T20II.\n  Fotografe a folha inteira e envie ao suporte para identifica\xe7\xe3o.</p>\n\n\n\n<h3 class="wp-block-heading">3. O papel mostra IP 0.0.0.0</h3>\n\n\n\n<p>O endere\xe7o <code>0.0.0.0</code> indica que a impressora ainda n\xe3o recebeu um IP v\xe1lido.\n  Confira o cabo de rede, o roteador e o switch; depois reinicie a impressora,\n  aguarde cerca de um minuto e repita o autoteste.</p>\n\n\n\n<h3 class="wp-block-heading">4. O papel mostra um IP iniciado por 169.254</h3>\n\n\n\n<p>Um endere\xe7o como <code>169.254.10.20</code> normalmente aparece quando o equipamento n\xe3o consegue receber\n  um IP do roteador. Verifique o cabo, a porta do switch e o funcionamento do DHCP.</p>\n\n\n\n<h2 class="wp-block-heading">O que enviar para o suporte</h2>\n\n\n\n<p>Para agilizar o atendimento, envie:</p>\n\n\n\n<ol class="wp-block-list">\n<li>Uma foto completa e leg\xedvel do autoteste;</li>\n\n\n\n<li>Uma foto da etiqueta com o modelo da impressora;</li>\n\n\n\n<li>Uma foto das conex\xf5es e dos cabos;</li>\n\n\n\n<li>O endere\xe7o IP encontrado, caso apare\xe7a.</li>\n</ol>\n\n\n\n<h2 class="wp-block-heading" id="perguntas-frequentes">Perguntas frequentes</h2>\n\n\n\n<h3 class="wp-block-heading">Toda impressora t\xe9rmica possui endere\xe7o IP?</h3>\n\n\n\n<p>N\xe3o. Impressoras somente USB ou serial n\xe3o possuem IP pr\xf3prio. O IP existe nas vers\xf5es com Ethernet ou Wi-Fi.</p>\n\n\n\n<h3 class="wp-block-heading">Qual n\xfamero devo cadastrar no sistema?</h3>\n\n\n\n<p>Use o n\xfamero exibido ao lado de <strong>IP Address</strong>, <strong>IP</strong>, <strong>Local IP</strong> ou <strong>Printer IP</strong>.</p>\n\n\n\n<h3 class="wp-block-heading">O que significa IP 0.0.0.0?</h3>\n\n\n\n<p>Significa que a impressora ainda n\xe3o recebeu um endere\xe7o v\xe1lido da rede. Verifique o cabo e o roteador, reinicie e imprima o teste novamente.</p>\n\n\n\n<h3 class="wp-block-heading">Posso usar o mesmo procedimento em qualquer impressora?</h3>\n\n\n\n<p>N\xe3o. A maioria usa o bot\xe3o Feed durante a inicializa\xe7\xe3o, mas a MP-4200 TH, a Elgin i8 e a Epson TM-T20III possuem detalhes pr\xf3prios. Siga a se\xe7\xe3o do modelo correto.</p>\n\n\n\n<h3 class="wp-block-heading">Na MP-4200 TH devo apertar Avan\xe7o depois que o menu sair?</h3>\n\n\n\n<p>N\xe3o. Solte o bot\xe3o quando a impress\xe3o come\xe7ar e aguarde sem apertar nada. O autoteste inicia automaticamente.</p>\n\n\n\n<h2 class="wp-block-heading">Fontes t\xe9cnicas consultadas</h2>\n\n\n\n<p>Os procedimentos foram conferidos nos manuais t\xe9cnicos da Bematech MP-4200 TH,\n  Elgin i8, Elgin i9/i9 Full, Epson TM-T20II e Epson TM-T20III.\n  As imagens foram obtidas em p\xe1ginas oficiais dos fabricantes ou extra\xeddas dos respectivos manuais.</p>\n\n'}})})})}function d(o={}){const{wrapper:n}={...(0,s.R)(),...o.components};return n?(0,a.jsx)(n,{...o,children:(0,a.jsx)(c,{...o})}):c()}},8453:(o,n,e)=>{e.d(n,{R:()=>r,x:()=>i});var a=e(6540);const s={},t=a.createContext(s);function r(o){const n=a.useContext(t);return a.useMemo((function(){return"function"==typeof o?o(n):{...n,...o}}),[n,o])}function i(o){let n;return n=o.disableParentContext?"function"==typeof o.components?o.components(s):o.components||s:r(o.components),a.createElement(t.Provider,{value:n},o.children)}}}]);